import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: Theme;
  scale: number;
  compact: boolean;
  fontFamily: string;
}

const themeItems: Array<{ value: Theme; label: string }> = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const fontOptions = [
  { value: 'sans', label: 'Inter Tight', meta: 'Без засечек' },
  { value: 'display', label: 'Fraunces', meta: 'С засечками' },
  { value: 'mono', label: 'JetBrains Mono', meta: 'Моноширинный' },
];

const defaults: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  compact: false,
  fontFamily: 'sans',
};

export default function AppearanceSettingsScreen({
  value,
  onChange,
}: {
  value?: AppearanceSettings;
  onChange?: (settings: AppearanceSettings) => void;
}) {
  const [settings, setSettings] = useState<AppearanceSettings>(value ?? defaults);

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((current) => {
      const next = { ...current, ...patch };
      onChange?.(next);
      return next;
    });
  };

  const themeLabel = themeItems.find((item) => item.value === settings.theme)?.label ?? '';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', fontSize: '20px' }}>
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <JxToggle
        aria-label="Тема оформления"
        items={themeItems}
        value={settings.theme}
        onValueChange={(next) => update({ theme: next as Theme })}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(next) => update({ scale: next })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.compact}
        onChange={(event) => update({ compact: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        placeholder="Выберите шрифт"
        options={fontOptions}
        value={settings.fontFamily}
        onValueChange={(next) => update({ fontFamily: next })}
      />
    </section>
  );
}

